package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"log"
	"net/http"
	"sync"
	"time"
)

type AuthAttempt struct {
	Count     int
	LastReset time.Time
	Locked    bool
}

type InferenceServer struct {
	mu           sync.RWMutex
	attempts     map[string]*AuthAttempt
	apiKeys      map[string]string
	hmacSecret   []byte
	maxAttempts  int
	lockDuration time.Duration
}

func NewInferenceServer() *InferenceServer {
	secret := make([]byte, 32)
	if _, err := rand.Read(secret); err != nil {
		log.Fatal("Failed to generate secret:", err)
	}
	s := &InferenceServer{
		attempts:     make(map[string]*AuthAttempt),
		apiKeys:      make(map[string]string),
		hmacSecret:   secret,
		maxAttempts:  5,
		lockDuration: 15 * time.Minute,
	}
	s.apiKeys["user1"] = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6"
	s.apiKeys["user2"] = "f6e5d4c3b2a1f6e5d4c3b2a1f6e5d4c3"
	s.apiKeys["admin"] = "deadbeefcafebabe1234567890abcdef"
	return s
}

func (s *InferenceServer) generateToken(username string) string {
	mac := hmac.New(sha256.New, s.hmacSecret)
	mac.Write([]byte(username))
	return hex.EncodeToString(mac.Sum(nil))
}

func (s *InferenceServer) validateCredentials(username, apiKey string) bool {
	expectedKey, exists := s.apiKeys[username]
	if !exists {
		return false
	}
	return hmac.Equal([]byte(apiKey), []byte(expectedKey))
}

func (s *InferenceServer) checkRateLimit(identifier string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	attempt, exists := s.attempts[identifier]
	if !exists {
		s.attempts[identifier] = &AuthAttempt{Count: 0, LastReset: time.Now()}
		return true
	}

	if time.Since(attempt.LastReset) > s.lockDuration {
		attempt.Count = 0
		attempt.LastReset = time.Now()
		attempt.Locked = false
		return true
	}

	if attempt.Locked {
		return false
	}

	return true
}

func (s *InferenceServer) recordFailedAttempt(username, clientIP string) {
	s.mu.Lock()
	defer s.mu.Unlock()

	for _, id := range []string{clientIP, "user:" + username} {
		attempt, exists := s.attempts[id]
		if !exists {
			s.attempts[id] = &AuthAttempt{Count: 1, LastReset: time.Now()}
			continue
		}
		attempt.Count++
		if attempt.Count >= s.maxAttempts {
			attempt.Locked = true
		}
	}
}

func (s *InferenceServer) authHandler(w http.ResponseWriter, r *http.Request) {
	username := r.Header.Get("X-Username")
	apiKey := r.Header.Get("X-API-Key")
	clientIP := r.RemoteAddr

	if username == "" || apiKey == "" {
		http.Error(w, "Missing credentials", http.StatusUnauthorized)
		return
	}

	// Rate limit by both IP and username
	if !s.checkRateLimit(clientIP) || !s.checkRateLimit("user:"+username) {
		http.Error(w, "Too many attempts, account locked", http.StatusTooManyRequests)
		return
	}

	if !s.validateCredentials(username, apiKey) {
		s.recordFailedAttempt(username, clientIP)
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	// Reset on successful auth
	s.mu.Lock()
	delete(s.attempts, clientIP)
	delete(s.attempts, "user:"+username)
	s.mu.Unlock()

	token := s.generateToken(username)
	w.Header().Set("X-Session-Token", token)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	resp := map[string]string{
		"status": "authenticated",
		"user":   username,
	}
	_ = json.NewEncoder(w).Encode(resp)
}

func (s *InferenceServer) inferHandler(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Session-Token")
	username := r.Header.Get("X-Username")

	if token == "" || username == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	expectedToken := s.generateToken(username)
	if !hmac.Equal([]byte(token), []byte(expectedToken)) {
		http.Error(w, "Invalid token", http.StatusForbidden)
		return
	}

	// Enforce body size limit on actual reads (ContentLength is client-controlled).
	const maxBody = 10 * 1024 * 1024
	if r.ContentLength > maxBody {
		http.Error(w, "Upload too large", http.StatusRequestEntityTooLarge)
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	resp := map[string]string{
		"result": "inference_complete",
		"model":  "v2.1",
	}
	_ = json.NewEncoder(w).Encode(resp)
}

func main() {
	server := NewInferenceServer()

	mux := http.NewServeMux()
	mux.HandleFunc("/auth", server.authHandler)
	mux.HandleFunc("/infer", server.inferHandler)

	log.Println("ML Inference Server starting on :8443")
	log.Fatal(http.ListenAndServe(":8443", mux))
}
